using asdBlasHandle = void *;

enum class asdBlasStatus { BLAS_SUCCESS = 0, BLAS_FAILED = 1 };

enum class asdBlasSideMode_t { ASDBLAS_SIDE_LEFT = 0, ASDBLAS_SIDE_RIGHT };

