#include "log/log.h"

namespace wten {

template <typename T>
class TheTensor {
public:
    TheTensor(const std::vector<int64_t> &shape)
        : shape_(shape),
          strides_(std::vector<int64_t>(shape.size())),
          size_(compute_size(shape)),
          data_(new T[size_])
    {
        update_strides();
    }

    TheTensor(TheTensor &&tensor)
        : shape_(tensor.shape_),
          strides_(tensor.strides_),
          size_(tensor.size_),
          data_(tensor.move_data())
    {
    }

    TheTensor<T> &operator=(TheTensor<T> &&tensor)
    {
        delete[] data_;
        data_ = tensor.data_;
        size_ = tensor.size_;
        shape_ = tensor.shape_;
        strides_ = tensor.strides_;
        tensor.data_ = nullptr;
        return *this;
    }

    T &operator[](size_t index) const
    {
        return data_[index];
    }

    T *data() const
    {
        return data_;
    }

    T *move_data()
    {
        T *data = data_;
        data_ = nullptr;
        return data;
    }

    void free_data()
    {
        delete[] move_data();
    }

